code:
def solve(s):
    """Return True if s is a valid IPv4 address, else False.
    Conditions:
    - Four decimal numbers separated by '.'
    - Each number between 0 and 255 inclusive
    - No leading zeros unless the number is exactly '0'
    - Only digits allowed in each part
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # non-empty
        if not part:
            return False
        # all digits
        if not part.isdigit():
            return False
        # no leading zeros unless single '0'
        if len(part) > 1 and part[0] == '0':
            return False
        # range check
        try:
            val = int(part)
        except ValueError:
            return False
        if not (0 <= val <= 255):
            return False
    return True

