def solve(coins, amount):
    # DP for unbounded coin change (minimum number of coins)
    # Edge case: amount 0 -> 0 coins needed
    if amount == 0:
        return 0
    # Initialize DP array with a value larger than any possible number of coins
    INF = amount + 1  # max possible coins is amount (using coin of value 1), so amount+1 works as INF
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # if using coin c, we need dp[a-c] coins previously
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] != INF else -1

