def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    tail = []  # tail[i] = smallest possible tail of an IS of length i+1
    for x in nums:
        # find position to replace in tail
        pos = bisect.bisect_left(tail, x)
        if pos == len(tail):
            tail.append(x)
        else:
            tail[pos] = x
    return len(tail)

