def solve(coins, amount):
    """Return the minimum number of coins needed to make up the given amount.
    Unlimited supply of each coin value. Return -1 if impossible.
    """
    # Edge case: amount zero
    if amount == 0:
        return 0
    # Initialize DP array with a large sentinel value
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= i:
                cand = dp[i - c] + 1
                if cand < best:
                    best = cand
        dp[i] = best
    return dp[amount] if dp[amount] != INF else -1

