def solve(grid):
    """Count the number of islands (connected groups of 1s) in a grid.
    The grid may be empty or ragged (rows of varying lengths). Cells are
    connected orthogonally (up, down, left, right).
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = [ [False]*len(grid[r]) for r in range(rows) ]
    def neighbors(r, c):
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y] or grid[x][y] == 0:
                continue
            visited[x][y] = True
            for nx, ny in neighbors(x, y):
                if not visited[nx][ny] and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

