def solve(s: str) -> int:
    """Convert a Roman numeral to integer.
    Handles both uppercase and lowercase letters.
    Empty string returns 0.
    """
    if not s:
        return 0
    s = s.upper()
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
            'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        cur = vals.get(ch, 0)
        if cur < prev:
            total -= cur
        else:
            total += cur
            prev = cur
    return total

