def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Supports the operators '+', '-', '*', '/' where division truncates toward zero.
    Tokens are strings representing integers or operators.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            if len(stack) < 2:
                raise ValueError('Insufficient operands')
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            # operand
            stack.append(int(tok))
    if len(stack) != 1:
