def solve(intervals):
    if not intervals:
        return []
    # Normalize intervals to ensure start <= end and copy to new lists
    norm = []
    for iv in intervals:
        s, e = iv[0], iv[1]
        if s > e:
            s, e = e, s
        norm.append([s, e])
    norm.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = norm[0]
    for s, e in norm[1:]:
        if s <= cur_end:
            cur_end = max(cur_end, e)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e
    merged.append([cur_start, cur_end])
    return merged

