def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search (O(n log n)).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # find the first tail >= x (bisect_left) to maintain strictly increasing property
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

