def solve(s):
    """Return the length of the longest substring without repeating characters.
    Handles non-string inputs by returning 0.
    """
    if not isinstance(s, str):
        return 0
    last = {}
    max_len = 0
    start = 0
    for i, ch in enumerate(s):
        prev = last.get(ch)
        if prev is not None and prev >= start:
            start = prev + 1
        last[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

